CREATE OR REPLACE FUNCTION calculate_disf()
RETURNS numeric AS $$
DECLARE
    result numeric;
BEGIN
    SELECT AVG(
        (10 - ABS(o.airtempc - 15) / 10.0) * o.atmostransparency * (1 - o.humidityrate / 200.0) * (100 - o.lunardistdeg) / 100.0
    ) INTO result
    FROM signals s
    JOIN telescopes t ON s.telescref = t.telescregistry
    JOIN observatories o ON t.observstation = o.observstation;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

